export function parsePort(value: string): number {
  // Accept only canonical base-10 integer strings: a non-zero leading digit
  // followed by digits. This rejects empty/whitespace input, signs, decimals,
  // exponent notation, and trailing characters in one pass.
  if (!/^[1-9]\d*$/.test(value)) {
    throw new Error("Port must be a valid port number (1-65535).");
  }
  const port = Number(value);
  if (port > 65535) {
    throw new Error("Port must be a valid port number (1-65535).");
  }
  return port;
}

